policy_require_flag('file_downloads'); if(policy_request_blocked()){http_response_code(429);exit('Access temporarily restricted.');}$token=preg_replace('/[^A-Za-z0-9_-]/','',(string)($_GET['token']??''));$s=db()->prepare('SELECT * FROM file_objects WHERE public_token=? LIMIT 1');$s->execute([$token]);$f=$s->fetch();if(!$f){render_http_error_page(404,'File not found','This file may have moved or is no longer available.');exit; }if(!empty($f['trashed_at'])){http_response_code(410);exit('This file is in Trash and is not available.');}
