$unlocked=true;if(!empty($f['password_hash'])){if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$unlocked=password_verify((string)($_POST['password']??''),(string)$f['password_hash']);if($unlocked)$_SESSION['file_unlock_'.$f['id']]=time();}else $unlocked=(int)($_SESSION['file_unlock_'.$f['id']]??0)>time()-900;if(!$unlocked){?><!doctype html><html><body style="font-family:system-ui;background:#f6f8fc;display:grid;place-items:center;min-height:100vh"><form method="post" style="background:#fff;padding:28px;border-radius:16px;box-shadow:0 10px 30px #0001;width:min(420px,90%)"><?php echo csrf_field();?><h2>Password protected</h2><input name="password" type="password" required autofocus style="width:100%;padding:12px"><button style="margin-top:12px;padding:12px;width:100%">Unlock</button></form></body></html><?php exit;}}
