<?php else:?><p class="muted">Preview is not available for this file type.</p><?php endif;?></div><div class="actions"><?php if(!$viewOnly):?><button id="download" class="btn" type="button">Download</button><?php else:?><span class="muted">View-only share — downloading is disabled.</span><?php endif;?></div><p class="muted">Share this page without requiring the recipient to log in.</p></div></div><script>const FILE_ID=<?=json_encode((int)$f['id'])?>,FILE_TOKEN=<?=json_encode($f['public_token'])?>,CSRF=<?=json_encode((string)($_SESSION['_csrf']??''))?>;const sizeEl=document.getElementById('fileSize');if(sizeEl){let n=Number(sizeEl.dataset.bytes)||0,u=['B','KB','MB','GB','TB'],i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}sizeEl.textContent=(i===0?Math.round(n):n.toFixed(2))+' '+u[i];}document.getElementById('fullscreenImage')?.addEventListener('click',async()=>{const box=document.querySelector('.image-preview-wrap');try{if(!document.fullscreenElement)await box.requestFullscreen();else await document.exitFullscreen();}catch(e){}});fetch('/api/files/?action=asset_url&id='+FILE_ID+'&token='+encodeURIComponent(FILE_TOKEN)).then(r=>r.json()).then(j=>{document.querySelectorAll('[data-src]').forEach(x=>x.src=j.url);}).catch(()=>{});if(<?=json_encode(str_starts_with($f['mime_type'],'text/'))?>){fetch('/api/files/?action=preview&id=<?=json_encode((int)$f['id'])?>&token=<?=json_encode($f['public_token'])?>').then(r=>r.json()).then(j=>{if(j.content!==undefined){document.getElementById('codePreview').textContent=j.content;if(window.hljs)hljs.highlightElement(document.getElementById('codePreview'));}}).catch(()=>{});}const d=document.getElementById('download');if(d)d.addEventListener('click',async()=>{try{const r=await fetch('/api/files/?action=download_start',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({id:FILE_ID,token:FILE_TOKEN})});const j=await r.json();if(!r.ok)throw Error(j.error||'Download unavailable');setTimeout(()=>navigator.sendBeacon('/api/files/?action=complete_download',new Blob([JSON.stringify({id:FILE_ID,token:FILE_TOKEN,nonce:<?=json_encode(hash('sha256',(string)$f['public_token'].(string)$f['id']))?>})],{type:'application/json'})),2000);location.href=j.url;}catch(e){const n=document.createElement('div');n.className='download-error';n.setAttribute('role','alert');n.textContent=e.message||'Download unavailable';document.querySelector('.card').appendChild(n);}});</script><script src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.11.1/highlight.min.js"></script><script>if(window.hljs){const x=document.getElementById('codePreview');if(x)hljs.highlightElement(x);}</script></body></html>
